contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log) public payable {
        require(log != address(0));

        uint256 beforeBalance = address(c).balance;

        bool reverted;
        c.SetLogFile(log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

